/// The value of the variable the design calls `name`, in `theme`.
pub(super) fn lookup(name: &str, theme: PidTheme) -> Option<TokenValue> {
    if let Some(token) = ColorToken::ALL.iter().find(|token| token.name() == name) {
        return Some(TokenValue::Color(token.rgba(theme)));
    }
    if let Some(token) = NumberToken::ALL.iter().find(|token| token.name() == name) {
        return Some(TokenValue::Number(token.value(theme)));
    }
    if let Some(token) = TextToken::ALL.iter().find(|token| token.name() == name) {
        return Some(TokenValue::Text(token.value(theme)));
    }
    None
}
